WITH ranked AS (SELECT * FROM (SELECT *, RANK() OVER (PARTITION BY city ORDER BY rating ASC NULLS FIRST) AS latest_rank FROM suppliers) x WHERE latest_rank = 1) SELECT id, country, city, rating, latest_rank, CASE WHEN city RLIKE '^(Chiang Mai|New York)$' THEN 'GROUP_B' WHEN city RLIKE '^(Bangkok|Singapore)$' THEN 'OTHER_ZONE' ELSE 'PRIORITY' END AS city_zone FROM ranked ORDER BY city ASC, id ASC;
